function poolTime(durations, size) {
  const threads = new Array(size).fill(0);
  for (const d of durations) {
    let i = 0;
    for (let j = 1; j < size; j++) if (threads[j] < threads[i]) i = j;
    threads[i] += d;
  }
  return Math.max(0, ...threads);
}

