class Server {
  constructor() {
    this.inFlight = new Set();
    this.closing = false;
    this.closed = false;
    this.log = [];
  }
  start(id) {
    if (this.closing) return this.log.push('rejected:' + id);
    this.inFlight.add(id);
  }
  end(id) {
    this.inFlight.delete(id);
    this.maybeClose();
  }
  shutdown() {
    this.closing = true;
    this.maybeClose();
  }
  maybeClose() {
    if (this.closing && !this.closed && this.inFlight.size === 0) {
      this.closed = true;
      this.log.push('closed');
    }
  }
}

