coding.referenceSolution:
function findCycle(deps) {
  const done = new Set();
  const stack = [];
  const onStack = new Set();
  function visit(m) {
    if (onStack.has(m)) return stack.slice(stack.indexOf(m)).concat(m);
    if (done.has(m)) return null;
    stack.push(m);
    onStack.add(m);
    for (const d of deps[m] || []) {
      const found = visit(d);
      if (found) return found;
    }
    stack.pop();
    onStack.delete(m);
    done.add(m);
    return null;
  }
  for (const m of Object.keys(deps)) {
    const found = visit(m);
    if (found) return found;
  }
  return null;
}

